package com.arxyt.territorycontrolcompat.network;
import com.arxyt.territorycontrol.core.TCPermissions; import com.arxyt.territorycontrolcompat.data.CompatSavedData; import net.minecraft.network.FriendlyByteBuf; import net.minecraft.server.level.ServerPlayer; import net.minecraftforge.network.*; import java.util.function.Supplier;
public record SaveCompatPacket(CompatSavedData.Config config){public void encode(FriendlyByteBuf b){new CompatConfigPacket(config,false).encode(b);}public static SaveCompatPacket decode(FriendlyByteBuf b){return new SaveCompatPacket(CompatConfigPacket.decode(b).config());}public static void handle(SaveCompatPacket p,Supplier<NetworkEvent.Context> s){s.get().enqueueWork(()->{ServerPlayer player=s.get().getSender();if(player!=null&&TCPermissions.canManage(player))CompatSavedData.get(player.serverLevel()).setConfig(p.config());});s.get().setPacketHandled(true);}}
